// Event-handler unit checks in a stub DOM, not browser/OS input simulation.
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.resolve('outputs/intent-compiler-v2/input-interruption-r60');
function target(){const listeners={};return {style:{},textContent:'',disabled:false,firstChild:{},addEventListener(n,f){(listeners[n]??=[]).push(f)},emit(n,e={}){for(const f of listeners[n]||[])f(e)},setAttribute(){},setPointerCapture(){}};}
const results={};
for(const arm of ['V1','V2']){
 const source=fs.readFileSync(path.join(root,arm,'index.html'),'utf8');
 const original=fs.readFileSync(path.resolve('outputs/intent-compiler-v2/outcome-feedback-r53/runs/r53/repair',arm,'workspace/index.html'));
 assert.equal(Buffer.compare(Buffer.from(source),original),0);
 results[arm]=[];
 for(const [input,event] of [['pointer','blur'],['key','blur'],['pointer','visibilitychange'],['key','visibilitychange'],['pointer','pointercancel'],['pointer','lostpointercapture']]){
  const nodes=new Map(),doc=target(),win=target();
  const get=id=>{if(!nodes.has(id))nodes.set(id,target());return nodes.get(id)};
  doc.getElementById=get;doc.querySelector=()=>target();doc.hidden=false;
  const ctx=new Proxy({},{get:(o,k)=>k in o?o[k]:()=>{}});
  get('game').getContext=()=>ctx;
  let frame;
  const sandbox={document:doc,window:win,localStorage:{getItem:()=>null,setItem(){}},matchMedia:()=>({matches:true}),requestAnimationFrame:f=>{frame=f},console};
  vm.runInNewContext(source.match(/<script>([\s\S]*?)<\/script>/)[1],sandbox);
  const button=get('throw'),e={button:0,pointerId:7,code:'Space',target:button,repeat:false,preventDefault(){}};
  const begin=()=>input==='key'?doc.emit('keydown',e):button.emit('pointerdown',e);
  const end=()=>input==='key'?doc.emit('keyup',e):button.emit('pointerup',e);
  begin();for(let t=100;t<=400;t+=25)frame(t);
  const charged=get('power').textContent;
  assert.ok(parseInt(charged)>0);
  if(event==='blur')win.emit(event);else if(event==='visibilitychange'){doc.hidden=true;doc.emit(event);doc.hidden=false;doc.emit(event)}else button.emit(event,e);
  assert.equal(get('power').textContent,'0%');assert.equal(button.disabled,false);
  const cancelled=button.textContent;
  end();assert.equal(button.textContent,cancelled);assert.equal(button.disabled,false);
  begin();for(let t=500;t<=800;t+=25)frame(t);end();assert.equal(button.disabled,true);
  results[arm].push({input,event,chargedBefore:charged,cancelledPower:'0%',staleReleaseIgnored:true,newThrowAccepted:true});
 }
}
fs.writeFileSync(path.join(root,'handlers-independent.json'),JSON.stringify({method:'Unmodified script executed in Node VM with stub DOM/canvas/storage and explicit frame steps. Invoke registered handlers; no real browser focus or pointer delivery.',results,limits:'Does not prove OS blur, real pointer capture, touchscreen or background animation timing. Actual held-input browser test remains unverified.'},null,2));
console.log('PASS: 12 cancellation/release/restart handler cases; browser interruption NOT VERIFIED');
